// Stages one fresh private root for a built end-to-end run.
//
// Nothing here is shared with a developer's installation: the root is a 0700
// `mkdtemp`, the Runtime key is generated by the private launcher into its own
// 0700 directory, and the TeamMem paths are all beneath the same root. The
// live TeamMem installation (~/.local/share/teammem, ~/.config/teammem and the
// overlay) is never read or written.

import { spawnSync } from "node:child_process";
import { randomBytes } from "node:crypto";
import { chmodSync, mkdirSync, mkdtempSync, realpathSync, writeFileSync } from "node:fs";
import { loadavg, tmpdir } from "node:os";
import path from "node:path";

import { RUNTIME_PIN, TEAMMEM_SOURCE } from "./pins.mjs";

export const NODE24 = "/opt/homebrew/opt/node@24/bin/node";
export const PYTHON = "/opt/homebrew/bin/python3";
export const RECORDING_KEY_ENV = "E2E_RUNTIME_RECORDING_KEY";
export const PROVIDER_CREDENTIAL_ENV = "E2E_PROVIDER_CREDENTIAL";
/** The synthetic provider credential; the launcher exports it to the gateway only. */
export const PROVIDER_CREDENTIAL = "e2e-synthetic-provider-credential-not-real";
/** See the comment on the bridge static config below. */
export const CAPTURE_FRAME_LIMIT = 51;

const quote = (value) => `'${String(value).replaceAll("'", "'\\''")}'`;

export function run(command, argv, options = {}) {
  const started = Date.now();
  const result = spawnSync(command, argv, { encoding: "utf8", timeout: 900_000, ...options });
  return {
    command: [command, ...argv], exit: result.status, signal: result.signal,
    stdout: result.stdout ?? "", stderr: result.stderr ?? "",
    durationMs: Date.now() - started, loadAverage: loadAverage(),
  };
}

export function loadAverage() {
  return loadavg().map((value) => Number(value.toFixed(2)));
}

function makeDirectories(root, names, mode = 0o700) {
  const made = {};
  for (const [key, relative] of Object.entries(names)) {
    const directory = path.join(root, relative);
    mkdirSync(directory, { recursive: true, mode });
    chmodSync(directory, mode);
    made[key] = directory;
  }
  return made;
}

/** Copies the BUILT package, never `src`. APFS clones when it can. */
function stageBuiltApplication(repository, appDir) {
  mkdirSync(appDir, { recursive: true, mode: 0o700 });
  const copies = [];
  for (const entry of ["dist", "migrations", "node_modules", "package.json", "e2e"]) {
    const source = path.join(repository, entry);
    const cloned = run("/bin/cp", ["-Rc", source, appDir]);
    copies.push(cloned.exit === 0 ? cloned : run("/bin/cp", ["-R", source, appDir]));
  }
  const failed = copies.filter((copy) => copy.exit !== 0);
  if (failed.length > 0) throw new Error(`staging the built package failed: ${failed.map((copy) => copy.stderr.trim()).join("; ")}`);
  return copies;
}

export function stage({ repository }) {
  const root = realpathSync(mkdtempSync(path.join(realpathSync(tmpdir()), "meeting-e2e-")));
  chmodSync(root, 0o700);

  const directories = makeDirectories(root, {
    app: "app", stateRoot: "state", control: "bridge-control", configDir: "config",
    recordingsDir: "data/recordings", outboxDir: "data/outbox", receiptsDir: "data/receipts", teamVaultDir: "data/team-vault",
    runtimeRoot: "runtime", runtimeModelsDir: "runtime/models", runtimeKeyDir: "runtime/key",
    teammem: "teammem", evidence: "evidence",
  });

  const copies = stageBuiltApplication(repository, directories.app);

  // --- Runtime: pinned artefacts and the private launcher -------------------
  const gatewayPath = path.join(directories.runtimeRoot, "conversation-runtime-gateway");
  const sdkTarball = path.join(directories.runtimeRoot, path.basename(RUNTIME_PIN.sdkTarball.path));
  for (const [source, destination] of [[RUNTIME_PIN.gateway.path, gatewayPath], [RUNTIME_PIN.sdkTarball.path, sdkTarball]]) {
    const copied = run("/bin/cp", ["-c", source, destination]);
    if (copied.exit !== 0 && run("/bin/cp", [source, destination]).exit !== 0) throw new Error(`staging ${source} failed`);
  }
  chmodSync(gatewayPath, 0o700);

  const keyPath = path.join(directories.runtimeKeyDir, "recording.key");
  const launcherPath = path.join(root, "runtime-launcher");
  const gatewayConfigPath = path.join(directories.runtimeRoot, "gateway.toml");
  const launcherLog = path.join(directories.runtimeRoot, "launcher.stderr.log");
  // The key is generated on first launch into a 0700 directory as a 0600 file
  // and exported to the gateway child only; the Meeting parent never sees it.
  writeFileSync(launcherPath, `#!/bin/sh
exec 2>>${quote(launcherLog)}
if [ ! -f ${quote(keyPath)} ]; then
  umask 077
  /usr/bin/openssl rand -hex 32 > ${quote(keyPath)} || exit 2
fi
IFS= read -r ${RECORDING_KEY_ENV} < ${quote(keyPath)} || exit 2
[ -n "$${RECORDING_KEY_ENV}" ] || exit 2
export ${RECORDING_KEY_ENV}
${PROVIDER_CREDENTIAL_ENV}=${quote(PROVIDER_CREDENTIAL)}
export ${PROVIDER_CREDENTIAL_ENV}
printf '%s\\n' "$$" >> ${quote(path.join(directories.runtimeRoot, "gateway-pids.txt"))}
exec ${quote(gatewayPath)} "$@"
`, { mode: 0o700 });

  // --- Feishu secret reference and the scripted client's static config ------
  const appSecretFile = path.join(directories.configDir, "app-secret");
  writeFileSync(appSecretFile, `${randomBytes(16).toString("hex")}\n`, { mode: 0o600 });
  const bridgeStaticConfigPath = path.join(directories.configDir, "bridge-static.json");
  writeFileSync(bridgeStaticConfigPath, JSON.stringify({
    schema: "feishu-bridge-config/v1", bundleVersion: "e2e-scripted",
    controlDir: directories.control,
    // Fifty-one 20 ms frames: more than twice the roughly twenty frames that
    // was the old ceiling, and the exact length D032 §1 was measured at. Its
    // two alignment pages re-encode to 46575 and 37801 private bytes, both
    // past the 32768-byte budget that used to refuse them, so the run proves
    // the fixed bound. Two hundred frames were tried and reverted: the child
    // paces one frame per 20 ms, and on a loaded machine only 101 of them fit
    // inside the fixed media-capture budget, which may not be widened.
    captureFrameLimit: CAPTURE_FRAME_LIMIT,
    // One observed participant, so the closed-meeting attendance the artifact
    // contract requires comes from real bridge-observed UI events rather than
    // anything the harness writes into the artifact.
    participants: [{ feishuUserId: "ou_e2e_organizer", displayName: "Scripted Organizer" }],
    audio: { captureDisplayId: 1, outputDeviceUid: "e2e-scripted-output" },
  }), { mode: 0o600 });

  const standaloneConfigPath = path.join(directories.configDir, "standalone.json");
  const standaloneConfig = {
    schema: "meeting-agent-standalone/v1",
    stateRoot: directories.stateRoot,
    feishu: { region: "feishu", tenantKey: "e2e-tenant", appId: "cli_0123456789abcdef", appSecretFile },
    agentIdentity: { aliases: ["Meetbot"] },
    dataPaths: {
      recordingsDir: directories.recordingsDir, outboxDir: directories.outboxDir,
      receiptsDir: directories.receiptsDir, teamVaultDir: directories.teamVaultDir,
    },
    runtime: { launcherPath, gatewayConfigPath, protocolVersion: 4 },
    bridgeSlots: [{
      physicalClientId: "e2e-mac-1", bridgeId: "e2e-bridge-1", executable: NODE24,
      staticConfigPath: bridgeStaticConfigPath,
      argv: [path.join(directories.app, "e2e/fixtures/e2e-bridge-child.mjs")],
      cooperativeGraceMs: 5000,
    }],
  };
  writeFileSync(standaloneConfigPath, JSON.stringify(standaloneConfig, null, 2), { mode: 0o600 });

  return {
    root, directories, copies,
    gatewayPath, sdkTarball, launcherPath, gatewayConfigPath, launcherLog, keyPath,
    appSecretFile, bridgeStaticConfigPath, standaloneConfigPath, standaloneConfig,
    entryPath: path.join(directories.app, "e2e/entry.mjs"),
    mainPath: path.join(directories.app, "dist/src/main.js"),
    gatewayPidsPath: path.join(directories.runtimeRoot, "gateway-pids.txt"),
    teammemSource: TEAMMEM_SOURCE,
  };
}
